import Foundation
import ItomaCore
import ItomaHistory
import ItomaStorage

struct Request: Encodable {
    struct Clip: Encodable { let from: Double; let until: Double }
    let period: ReflectionPrototypePeriod
    let day: String
    var clippedTo: Clip?
}
struct Sample: Encodable { let request: Request; let response: ReflectionReadSnapshot }

// Synthetic SQLite only. UUIDs and capture times intentionally remain generated by the real
// repository; this is a transport/calendar fixture, not a deterministic OS restriction record.
var result: [String: [Sample]] = [:]
let requestedDay = CommandLine.arguments.dropFirst().first ?? "2026-11-10"
for scenario in ["notRecorded", "observed", "incomplete", "deleted"] {
    let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    let control = try ControlRepository.create(at: directory.appendingPathComponent("control.sqlite"),
        initialPolicy: PolicySnapshot(revision: PolicyRevision(0), rules: [], priorityOrder: []), activation: .enabled)
    let history = try HistoryRepository.create(at: directory.appendingPathComponent("history.sqlite"),
        capacity: HistoryCapacityPolicy(warningBytes: 500_000, maximumBytes: 1_000_000))
    if scenario != "notRecorded" {
        try control.installReflectionCapture(capacity: HistoryOutboxCapacity(maximumPendingEvents: scenario == "incomplete" ? 1 : 100))
        if scenario == "incomplete" {
            _ = try control.setActivation(.paused, expectedSequence: control.readSnapshot().snapshotSequence)
        }
        if scenario == "deleted" { try history.deleteAllRecords(from: control) }
        try control.transferReflection(to: history)
    }
    let now = try Instant(secondsSince1970: Date().timeIntervalSince1970)
    let initial = try history.readReflection(period: .week, day: requestedDay, timeZone: "UTC", now: now)
    var samples: [Sample] = []
    func read(_ request: Request) throws -> ReflectionReadSnapshot {
        let clip = try request.clippedTo.map { try ReflectionPrototypeInterval(from: Instant(secondsSince1970: $0.from), until: Instant(secondsSince1970: $0.until)) }
        let value = try history.readReflection(period: request.period, day: request.day, timeZone: "UTC",
            expectedToken: initial.token, clippedTo: clip, now: now)
        samples.append(Sample(request: request, response: value)); return value
    }
    _ = try read(Request(period: .week, day: requestedDay))
    _ = try read(Request(period: .week, day: initial.anchor))
    for anchor in [initial.previousAnchor, initial.nextAnchor].compactMap({ $0 }) {
        _ = try read(Request(period: .week, day: anchor))
    }
    let month = try read(Request(period: .month, day: requestedDay))
    var months = [month]
    _ = try read(Request(period: .month, day: month.anchor))
    for anchor in [month.previousAnchor, month.nextAnchor].compactMap({ $0 }) {
        months.append(try read(Request(period: .month, day: anchor)))
    }
    for value in months {
        for row in value.buckets {
            let week = try read(Request(period: .week, day: row.day, clippedTo: Request.Clip(from: row.from, until: row.until)))
            _ = try read(Request(period: .week, day: week.anchor))
        }
    }
    result[scenario] = samples
    try history.close(); try control.close()
    try FileManager.default.removeItem(at: directory)
}
let encoder = JSONEncoder()
encoder.outputFormatting = [.sortedKeys, .prettyPrinted]
FileHandle.standardOutput.write(try encoder.encode(result))
FileHandle.standardOutput.write(Data([10]))
